/// `ColumnPredicate` read back; a refusal is the typed `DecodeError`.
let decodeColumnPredicate (j: JVal) : Result<ColumnPredicate, DecodeError> = decColumnPredicate j
/// `decodeColumnPredicate` under the strict-members reading: an undeclared member is `UndeclaredMember`
/// at it. A type parameter's payload is its decoder's to police.
let decodeColumnPredicateStrict (j: JVal) : Result<ColumnPredicate, DecodeError> =
    strictColumnPredicate j |> Result.bind (fun () -> decColumnPredicate j)

/// `SortKey` as a JSON value.
let encodeSortKey (v: SortKey) : JVal = encSortKey v
/// `SortKey` read back; a refusal is the typed `DecodeError`.
let decodeSortKey (j: JVal) : Result<SortKey, DecodeError> = decSortKey j
/// `decodeSortKey` under the strict-members reading.
let decodeSortKeyStrict (j: JVal) : Result<SortKey, DecodeError> =
    strictSortKey j |> Result.bind (fun () -> decSortKey j)